    giraffe_patches = image_patch.find("giraffe stomach")

    if not zed_patches or not giraffe_patches:
        return image_patch

    min_distance = float('inf')
    closest_zed = None

    for zed in zed_patches:
        for giraffe in giraffe_patches:
            dist = distance(zed, giraffe)
            if dist < min_distance:
                min_distance = dist
                closest_zed = zed

    return closest_zed

