    image_patch = ImagePatch(image)
    table_patches = image_patch.find("table")
    if not table_patches: 
        return image_patch

    table = table_patches[0]
    all_objects = image_patch.find("object")

    free_parts = []
    for obj in all_objects:
        if not is_overlapping(table, obj):
            free_parts.append(obj)

